class NoTemporaryPathsTests(unittest.TestCase):
    def test_scripts_use_approved_temporary_paths(self) -> None:
        allowed: Counter[tuple[str, str]] = Counter()
        for entry in ALLOWED_LINES.splitlines():
            location, _reason, source = entry.split("\t", 2)
            filename, _line_number = location.rsplit(":", 1)
            allowed[filename, source] += 1

        paths = subprocess.check_output(
            ["git", "ls-files", "-z", "--cached", "--others", "--exclude-standard", "--", "scripts"],
            cwd=ROOT,
        )
        unexpected: list[str] = []
        for filename in sorted({os.fsdecode(name) for name in paths.split(b"\0") if name}):
            path = ROOT / filename
            if path.is_symlink():
                content = os.fspath(path.readlink())
            elif path.is_file():
                contents = path.read_bytes()
                if TEMP_COMPONENT not in contents:
                    continue
                content = contents.decode("utf-8", errors="surrogateescape")
            else:
                continue
            for line_number, line in enumerate(content.splitlines(), 1):
                if TEMP_PATH.search(line):
                    key = (filename, line)
                    if allowed[key]:
                        allowed[key] -= 1
                    else:
                        unexpected.append(f"{filename}:{line_number}: {line.strip()[:180]}")

        self.assertFalse(unexpected, f"{len(unexpected)} unapproved temporary paths:\n"
                         + "\n".join(unexpected[:30]))
